// MARK: - Type

enum ZOTextStyle: CaseIterable {
    case display, title, section, body, label, caption, mini, metric, timer, timerHero

    struct Spec {
        let size: CGFloat
        let lineHeight: CGFloat
        let weight: CGFloat
        let width: CGFloat
        let tracking: CGFloat
        let textStyle: UIFont.TextStyle
        let tabular: Bool
        let maxSize: DynamicTypeSize?
    }

    var spec: Spec {
        switch self {
        case .display: Spec(size: 34, lineHeight: 40, weight: 700, width: 100, tracking: -0.4, textStyle: .largeTitle, tabular: false, maxSize: nil)
        case .title: Spec(size: 24, lineHeight: 30, weight: 600, width: 100, tracking: -0.2, textStyle: .title2, tabular: false, maxSize: nil)
        case .section: Spec(size: 17, lineHeight: 22, weight: 600, width: 100, tracking: 0, textStyle: .headline, tabular: false, maxSize: nil)
        case .body: Spec(size: 17, lineHeight: 24, weight: 400, width: 100, tracking: 0, textStyle: .body, tabular: false, maxSize: nil)
        case .label: Spec(size: 15, lineHeight: 20, weight: 500, width: 100, tracking: 0, textStyle: .subheadline, tabular: false, maxSize: nil)
        case .caption: Spec(size: 13, lineHeight: 18, weight: 400, width: 100, tracking: 0, textStyle: .footnote, tabular: false, maxSize: nil)
        case .mini: Spec(size: 11, lineHeight: 13, weight: 500, width: 100, tracking: 0.1, textStyle: .caption2, tabular: false, maxSize: nil)
        case .metric: Spec(size: 32, lineHeight: 36, weight: 700, width: 85, tracking: 0, textStyle: .title1, tabular: true, maxSize: .xxxLarge)
        case .timer: Spec(size: 64, lineHeight: 64, weight: 600, width: 75, tracking: -0.5, textStyle: .largeTitle, tabular: true, maxSize: .xxxLarge)
        case .timerHero: Spec(size: 112, lineHeight: 108, weight: 700, width: 75, tracking: -2, textStyle: .largeTitle, tabular: true, maxSize: .large)
        }
    }
}

private enum ZOFontAxis {
    static let width = 0x77647468   // 'wdth'
    static let weight = 0x77676874  // 'wght'
}

private enum ZOVariableFont {
    // The variable and legacy static Regular fonts share a PostScript name.
    // Resolve this exact resource without changing global font registration.
    static let descriptor: CTFontDescriptor? = {
        guard let url = Bundle.main.url(forResource: "InstrumentSans-Variable", withExtension: "ttf"),
              let descriptors = CTFontManagerCreateFontDescriptorsFromURL(url as CFURL) as? [CTFontDescriptor]
        else { return nil }
        return descriptors.first
    }()
}

extension ZOTextStyle {
    /// Instrument Sans variable font at this style's weight and width, scaled for Dynamic Type.
    func ctFont(for size: DynamicTypeSize) -> CTFont {
        let s = spec
        let capped = s.maxSize.map { min(size, $0) } ?? size
        let traits = UITraitCollection(preferredContentSizeCategory: UIContentSizeCategory(capped))
        let scaledSize = UIFontMetrics(forTextStyle: s.textStyle).scaledValue(for: s.size, compatibleWith: traits)
        guard let resource = ZOVariableFont.descriptor else {
            assertionFailure("InstrumentSans-Variable.ttf is missing or unreadable in this target.")
            return CTFontCreateWithName("Helvetica" as CFString, scaledSize, nil)
        }
        let descriptor = CTFontDescriptorCreateCopyWithAttributes(resource, [
            kCTFontVariationAttribute: [
                ZOFontAxis.width: s.width,
                ZOFontAxis.weight: s.weight
            ]
        ] as CFDictionary)
        return CTFontCreateWithFontDescriptor(descriptor, scaledSize, nil)
    }
}

private struct ZOTextModifier: ViewModifier {
    let style: ZOTextStyle
    @Environment(\.dynamicTypeSize) private var dynamicTypeSize

    func body(content: Content) -> some View {
        let font = style.ctFont(for: dynamicTypeSize)
        let spec = style.spec
        let scale = CTFontGetSize(font) / spec.size
        let lineHeight = CTFontGetAscent(font) + CTFontGetDescent(font) + CTFontGetLeading(font)
        let base = Font(font)
        content
            .font(spec.tabular ? base.monospacedDigit() : base)
            .tracking(spec.tracking)
            .lineSpacing(max(0, spec.lineHeight * scale - lineHeight))
    }
}

extension View {
    /// The only way to set text in the app: `Text("Today").zoText(.display)`.
    func zoText(_ style: ZOTextStyle) -> some View { modifier(ZOTextModifier(style: style)) }
}

