    static func brace(_ d: Double) -> Animation { .timingCurve(0.45, 0, 0.55, 1, duration: d) }

    /// Reduce Motion: same states, opacity only.
    static func crossfade(panel: Bool = false) -> Animation { .linear(duration: panel ? label : micro) }

