extension Image {
    /// SF Symbol in the system's one weight and scale. Outline unless the symbol's fill means state.
    func zoIcon(_ size: CGFloat = ZOIcon.row) -> some View {
        self.symbolRenderingMode(.monochrome)
            .font(.system(size: size, weight: .medium))
            .imageScale(.medium)
            .frame(width: size, height: size)
    }
}

